text:
{
  "questions": [
    {
      "n": 1,
      "start": "Hat Coop das Areal gekauft",
      "end": "oder wird dies im Baurecht übernommen?"
    },
    {
      "n": 2,
      "start": "Wurde Coop zur Mitbeteiligung",
      "end": "der Kosten für Infrastruktur verpflichtet?"
    },
    {
      "n": 3,
      "start": "Welche zusätzlichen Steuereinnahmen",
      "end": "erhofft sich der Kanton in den nächsten Jahren?"
    },
    {
      "n": 4,
      "start": "Wurden Coop Steuererleichterung",
      "end": "oder andere Wirtschaftsförderung gewährt?"
    },
    {
      "n": 5,
      "start": "Wie viele m2 stehen für weitere",
      "end": "Ansiedlung von Industrie und Gewerbe zur Verfügung?"
    },
    {
      "n": 6,
      "start": "Mit der S-Bahn Station Salina Raurica",
      "end": "ist östliche Teil dieses Gebietes gut mit dem ÖV erschlossen."
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Der Regierungsrat gibt aus Gründen einer nachhaltigen Arbeitsplatz- und Siedlungsentwicklung",
      "end": "die Areale im Baurecht an COOP ab."
    },
    {
      "n": 2,
      "start": "COOP wird die Verlängerung der Bahntrasse und den Bau von Verladeanlagen vollständig selbst",
      "end": "finanzieren. Für die Erstellung der Wasser-, Abwasser- und Energie-Infrastrukturanlagen ist COOP in Absprache mit der Gemeinde ebenfalls kostenpflichtig."
    },
    {
      "n": 3,
      "start": "Coop zählt bereits heute zu den guten und stetig zahlenden Steuerkunden in unserem Kanton.",
      "end": "Mit der Realisierung des Projekts und der Ansiedlung von Chocolat Halba in Pratteln wird die Basis des im Kanton Basel-Landschaft steuerbaren Gewinns vergrössert, was zu zusätzlichen Steuereinnahmen führen wird."
    },
    {
      "n": 4,
      "start": "Gemäss § 17 des Baselbieter Steuergesetzes kann der Regierungsrat nach Anhören des",
      "end": "Gemeinderates der Standortgemeinde zur Förderung der wirtschaftlichen Interessen des Kantons neuen Unternehmungen für das Jahr, in dem die Steuerpflicht im Kanton beginnt, und höchstens für die neun folgenden Jahre Steuererleichterungen gewähren."
    },
    {
      "n": 5,
      "start": "Grosse Teile der Gewerbeflächen im Perimeter von Salina Raurica sind bereits gewerblich genutzt.",
      "end": "Weitere baureife, d.h. erschlossene und zonenrechtlich verfügbare Areale stehen vorerst nicht zur Verfügung."
    },
    {
      "n": 6,
      "start": "Die Planung und Projektierung der Tramverbindung geht von einer vollständigen Auslastung des",
      "end": "gesamten Areals von Salina Raurica aus."
    }
  ],
  "submitter": "Dominik Straumann",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": {
    "start": "Die Zielrichtung, welche der Landrat mit diesen Aufträgen formuliert hat, ist fachlich sinnvoll und wird von der Regierung mit getragen.",
    "end": "Sie deckt sich mit den strategischen Zielen der Regierung unter anderem in der Absicht, die gute Standortqualität durch leistungsfähige Infrastruktur zu erhalten."
  }
}
